#!/usr/bin/env python3
"""Materialize the validated generated Rust interfaces without network access."""

from __future__ import annotations

import base64
import gzip
import os
import pathlib

CARGO_TOML_GZIP_BASE64 = ""

LIB_RS_GZIP_BASE64 = ""


def decode(value: str) -> bytes:
    return gzip.decompress(base64.b64decode(value))


def main() -> None:
    root = pathlib.Path(os.environ["RUNNER_TEMP"]) / "generated" / "generated" / "rust"
    root.joinpath("src").mkdir(parents=True, exist_ok=True)
    root.joinpath("Cargo.toml").write_bytes(decode(CARGO_TOML_GZIP_BASE64))
    root.joinpath("src", "lib.rs").write_bytes(decode(LIB_RS_GZIP_BASE64))

    if root.joinpath("Cargo.toml").stat().st_size != 364:
        raise RuntimeError("generated Cargo.toml payload size mismatch")
    if root.joinpath("src", "lib.rs").stat().st_size != 25245:
        raise RuntimeError("generated lib.rs payload size mismatch")


if __name__ == "__main__":
    main()
